+
+      let findings = [];
+      if (activeFilter === 'all') {
+        findings = [...map.security, ...map.performance, ...map.architecture];
+      } else {
+        findings = map[activeFilter] || [];
+      }
+
+      if (findings.length === 0) {
+        noMsg.classList.remove('hidden');
+        return;
+      }
+      noMsg.classList.add('hidden');
+
+      const tpl = document.getElementById('finding-tpl');
