+           : s === 'WARNING'  ? 'bg-amber-900 text-amber-300'
+           :                    'bg-blue-900 text-blue-300';
+    }
+
+    function escapeHtml(str) {
+      return str
+        .replace(/&/g, '&amp;')
+        .replace(/</g, '&lt;')
+        .replace(/>/g, '&gt;');
+    }
+
+    function colourDiff(escaped) {
+      return escaped.split('\n').map(line => {
+        if (line.startsWith('+'))       return `<span class="diff-add">${line}</span>`;
+        if (line.startsWith('-'))       return `<span class="diff-del">${line}</span>`;
+        if (line.startsWith('@@') || line.startsWith('diff') || line.startsWith('index') || line.startsWith('---') || line.startsWith('+++'))
+                                        return `<span class="diff-meta">${line}</span>`;
+        return line;
+      }).join('\n');
+    }
+
+    // ── Boot ───────────────────────────────────────────────────────
