cd backend; python -m uvicorn app.main:app --host 127.0.0.1 --port 8765 --timeout-graceful-shutdown 1 &
Start-Sleep 3
try {
  $health = Invoke-RestMethod http://127.0.0.1:8765/api/health
  Write-Host "health:" ($health | ConvertTo-Json)
  $samples = Invoke-RestMethod http://127.0.0.1:8765/api/samples
  Write-Host "samples keys:" ($samples.PSObject.Properties.Name -join ', ')
  $ui = Invoke-WebRequest http://127.0.0.1:8765/ -UseBasicParsing
  Write-Host "UI status:" $ui.StatusCode "content-type:" $ui.Headers.'Content-Type'
} finally {
  Stop-Process -Id (Get-NetTCPConnection -LocalPort 8765 -ErrorAction SilentlyContinue | Select-Object -First 1 -ExpandProperty OwningProcess) -Force -ErrorAction SilentlyContinue
}

